#include <iostream>
#include <string>
#include <vector>

class Name {
private:
    std::string firstName;
    std::string lastName;
public:
    Name(const std::string& first = "", const std::string& last = "")
        : firstName(first), lastName(last) {}
    std::string getFullName() const {
        return firstName + " " + lastName;
    }
};

class Person {
private:
    Name name; // Composition: Person owns Name by value
    Person* supervisor; // Same-class aggregation via pointer (avoids incomplete type error)
public:
    Person(const Name& n, Person* sup = nullptr)
        : name(n), supervisor(sup) {}

    void setSupervisor(Person* sup) {
        supervisor = sup;
    }

    void printInfo() const {
        std::cout << name.getFullName();
        if (supervisor != nullptr) {
            std::cout << " reports to " << supervisor->name.getFullName();
        } else {
            std::cout << " has no supervisor";
        }
        std::cout << std::endl;
    }
};

int main() {
    Person boss(Name("Alan", "Turing"));
    Person employee(Name("Ada", "Lovelace"), &boss);

    boss.printInfo();
    employee.printInfo();

    return 0;
}

#include <iostream>

class StackOfIntegers {
private:
    static constexpr int CAPACITY = 100;
    int elements[CAPACITY];
    int size{0};

public:
    StackOfIntegers() = default;

    bool isEmpty() const {
        return size == 0;
    }

    int peek() const {
        return elements[size - 1];
    }

    void push(int value) {
        if (size < CAPACITY) {
            elements[size++] = value;
        }
    }

    int pop() {
        return elements[--size];
    }

    int getSize() const {
        return size;
    }
};

int main() {
    StackOfIntegers stack;

    // Push 10 integers (0 to 9) to the stack
    for (int i = 0; i < 10; ++i) {
        stack.push(i);
    }

    std::cout << "Stack size: " << stack.getSize() << std::endl;
    std::cout << "Top element (peek): " << stack.peek() << std::endl;
    std::cout << "Elements in LIFO order:";

    // Pop elements until stack is empty
    while (!stack.isEmpty()) {
        std::cout << " " << stack.pop();
    }
    std::cout << std::endl;

    return 0;
}
